-- ─── Class records ─────────────────────────────────────────────────────────
-- Facet values are staged as text and resolved to dimension ids by name. The
-- joins are inner joins on purpose: a value outside the closed vocabulary
-- would drop its row rather than land in the table, and the count assertion
-- at the end of this file then fails, which aborts initialisation. Silent
-- partial loads are the failure mode this design refuses to allow.

CREATE TEMP TABLE _stage_classes (
    record_id text,
    class_title text,
    provider_name text,
    curriculum text,
    subject text,
    level text,
    delivery_mode text,
    instruction_language text,
    school_category text,
    education_stage text,
    class_status text,
    data_label text,
    verified_on text,
    retrieval_text text,
    keywords text,
    source_basis text
) ON COMMIT DROP;
COPY _stage_classes (record_id, class_title, provider_name, curriculum, subject, level, delivery_mode, instruction_language, school_category, education_stage, class_status, data_label, verified_on, retrieval_text, keywords, source_basis) FROM stdin WITH (FORMAT csv);
