-- ─── Self-check ────────────────────────────────────────────────────────────
-- Counts are baked in by the generator. If any of them is wrong the exception
-- aborts this transaction, and with it the container's initialisation, instead
-- of leaving a partially loaded corpus behind.

DO $$
DECLARE
    n bigint;
BEGIN
    SELECT count(*) INTO n FROM class_records;
    IF n <> 12 THEN
        RAISE EXCEPTION 'seed check failed: class_records has % row(s), expected 12', n;
    END IF;

    SELECT count(*) INTO n FROM curricula;
    IF n <> 5 THEN
        RAISE EXCEPTION 'seed check failed: curricula has % row(s), expected 5', n;
    END IF;

    SELECT count(*) INTO n FROM delivery_modes;
    IF n <> 11 THEN
        RAISE EXCEPTION 'seed check failed: delivery_modes has % row(s), expected 11', n;
    END IF;

    SELECT count(*) INTO n FROM instruction_languages;
    IF n <> 6 THEN
        RAISE EXCEPTION 'seed check failed: instruction_languages has % row(s), expected 6', n;
    END IF;

    SELECT count(*) INTO n FROM levels;
    IF n <> 17 THEN
        RAISE EXCEPTION 'seed check failed: levels has % row(s), expected 17', n;
    END IF;

    SELECT count(*) INTO n FROM providers;
    IF n <> 6 THEN
        RAISE EXCEPTION 'seed check failed: providers has % row(s), expected 6', n;
    END IF;

    SELECT count(*) INTO n FROM subjects;
    IF n <> 22 THEN
        RAISE EXCEPTION 'seed check failed: subjects has % row(s), expected 22', n;
    END IF;

    SELECT count(*) INTO n FROM synonyms;
    IF n <> 123 THEN
        RAISE EXCEPTION 'seed check failed: synonyms has % row(s), expected 123', n;
    END IF;

    -- FR-16 / FR-17: these two columns must be empty for every row. The API
    -- contract is built on it, so it is asserted at load time rather than
    -- trusted.
    SELECT count(*) INTO n
    FROM class_records
    WHERE fee_rm IS NOT NULL OR schedule IS NOT NULL;
    IF n <> 0 THEN
        RAISE EXCEPTION
            'seed check failed: % row(s) have fee_rm or schedule set; FR-16/FR-17 require both to be NULL', n;
    END IF;

    -- Every class must resolve to a full set of dimension rows. A NULL here
    -- would mean a join silently dropped something.
    SELECT count(*) INTO n
    FROM class_records
    WHERE provider_id IS NULL OR curriculum_id IS NULL OR subject_id IS NULL
       OR level_id IS NULL OR delivery_mode_id IS NULL
       OR instruction_lang_id IS NULL;
    IF n <> 0 THEN
        RAISE EXCEPTION 'seed check failed: % class row(s) have an unresolved facet', n;
    END IF;

    -- education_stage is redundant with level; a disagreement would make
    -- stage filters silently wrong.
    SELECT count(*) INTO n
    FROM class_records cr
    JOIN levels l ON l.level_id = cr.level_id
    WHERE l.stage <> cr.education_stage;
    IF n <> 0 THEN
        RAISE EXCEPTION
            'seed check failed: % row(s) where education_stage disagrees with the level stage', n;
    END IF;

    RAISE NOTICE 'Class Bot seed loaded and verified.';
END $$;

COMMIT;
